import {api,isDemo} from './api.js';
import config from './config.js';
import captchaConfig from './captcha-config.js';
import {createCaptchaClient} from './captcha.js';
import {privacyMarkup,termsMarkup} from './privacy.js';
import {legalDocumentMarkup} from './legal-documents.js';
import {enhanceFormFields} from './form-hints.js';
import {intro} from './intro.js';
import {cookiesMarkup} from './browser-storage.js';
import {safePhotoUrl} from './security.js';
import {categories,zones,labels,euro,rentalDays,today,distance,available,validateRental,nextActions,filterBookings,quoteRental,priceRuleLabels,escapeHtml as esc} from './domain.js';
import {icon,art} from './art.js';
import {mounts,accessoryTags,conditions,reportReasons,handoffItems,handoffGuidance,profileCompleteness,matchesTechnical,calendarMonth,chooseCalendarDate,PORTFOLIO_MAX,portfolioLabel} from './marketplace.js';
import {createPushClient} from './notifications.js';
import {preparePhoto,validatePhotoBatch,formatBytes} from './photos.js';
const privacyStatus={open:'Ricevuta · da gestire',reviewing:'In gestione',completed:'Gestione conclusa · leggi il riscontro',limited:'Cancellazione limitata · leggi il motivo'};
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const categoryIcons=['grid','camera','lens','light','audio','tripod','box'];
const state={legal:null,listings:[],bookings:[],favorites:readFavorites(),query:'',zone:'',category:'Tutto',sort:'recommended',max:'',start:'',end:'',onlyFavorites:false,free:false,route:'search',currentChat:null,mobileChatOpen:false,threads:[],reviewed:[],safety:{blocked:[],reports:[],moderator:false},calendar:null,brand:'',mount:'',power:'',accessory:'',condition:'',radius:'10',bookingRole:'all',bookingGroup:'all',photoDraft:null,counts:{messages:0,requests:0,byBooking:{}}};
const push=createPushClient(api,{demo:isDemo});
const captcha=createCaptchaClient({demo:isDemo,siteKey:captchaConfig.siteKey});
function readFavorites(){try{const value=JSON.parse(localStorage.getItem('sic-favorites')||'[]');return Array.isArray(value)?value.filter(x=>typeof x==='string'):[];}catch{return [];}}
const photo=(l)=>l.images?.[0]?`<img class="product-photo" src="${safeImage(l.images[0])}" alt="${esc(l.title)}" loading="lazy">`:art(l.art||({Camere:'camera',Obiettivi:'lens',Luci:'light',Audio:'audio',Supporti:'tripod',Accessori:'reflector'}[l.category]));
function safeImage(src){return esc(safePhotoUrl(src,{origin:location.origin,backend:config.url,demo:isDemo}));}
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short'});
const period=b=>b.kind==='inquiry'?'Domanda sull’annuncio':`${dateLabel(b.start_date)} → ${dateLabel(b.end_date)}`;
function toast(message){if(api.photoCleanupPending)message+=' Alcune vecchie foto sono ancora presenti: riprova da I tuoi dati → Pulisci foto inutilizzate.';const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
function error(e){const message=e.message||'Qualcosa non ha funzionato. Riprova.';if(modal.open){let el=modal.querySelector('.modal-action-error');if(!el){el=document.createElement('p');el.className='form-error modal-action-error';el.setAttribute('role','alert');modal.append(el);}el.textContent=message;el.scrollIntoView({block:'nearest'});}else toast(message);}
async function reload(){state.legal=!isDemo&&api.user()?await api.legalStatus():null;state.listings=await api.listings();state.bookings=api.user()?await api.bookings():[];state.safety=api.user()?await api.safetySettings():{blocked:[],reports:[],moderator:false};await refreshCounts();}
async function refreshCounts(){state.counts=api.user()?await api.notificationCounts():{messages:0,requests:0,byBooking:{}};renderBadges();await push.updateBadge(state.counts.messages+state.counts.requests);}
function counter(kind){return `<span class="unread-badge" data-count-kind="${kind}" hidden></span>`;}
function renderBadges(){for(const el of document.querySelectorAll('[data-count-kind]')){const n=Number(state.counts[el.dataset.countKind])||0;el.hidden=!n;el.textContent=n>99?'99+':String(n);el.setAttribute('aria-label',`${n} ${el.dataset.countKind==='messages'?'messaggi':'richieste'} non letti`);}for(const el of document.querySelectorAll('[data-thread-count]')){const n=Number(state.counts.byBooking?.[el.dataset.threadCount])||0;el.hidden=!n;el.textContent=n>99?'99+':String(n);}}
function header(){return `<div class="announcement">${isDemo?'<span class="demo-dot"></span> Demo · Annunci di prova, nessun noleggio reale':'Noleggio tra privati · Roma'}${isDemo?'<button data-action="about-demo">Scopri la demo '+icon('arrow')+'</button>':''}</div><header class="app-header"><a href="#search" data-action="explore" class="brand" aria-label="RENT TO A FRIEND · Esplora"><img class="brand-mark" src="/logo-mark.webp" width="96" height="96" alt="" fetchpriority="high"><span class="brand-name" aria-hidden="true"><span>RENT</span> <span>TO A</span> <span>FRIEND</span></span></a><form id="quick-search-form" class="header-search" role="search"><label class="sr-only" for="quick-search">Cerca attrezzatura</label>${icon('search')}<input id="quick-search" name="query" type="search" placeholder="Cerca una camera, una luce, un obiettivo…" value="${esc(state.query)}" autocomplete="off"><button type="submit" aria-label="Avvia ricerca">${icon('arrow')}</button></form><nav aria-label="Navigazione principale"><button data-action="show-favorites" class="nav-item ${state.route==='search'&&state.onlyFavorites?'active':''}" aria-label="Preferiti" aria-pressed="${state.route==='search'&&state.onlyFavorites}">${icon('heart')}<span>Preferiti</span></button>${[['messages','chat','Messaggi'],['bookings','calendar','Noleggi']].map(([route,i,label])=>`<a href="#${route}" class="nav-item ${state.route===route?'active':''}" ${state.route===route?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${counter(route==='messages'?'messages':'requests')}</a>`).join('')}</nav><div class="header-actions"><a class="avatar ${state.route==='profile'?'active':''}" href="#profile" aria-label="Profilo">${icon('user')}</a><button class="btn primary" data-action="publish">${icon('plus')}<span>Metti a noleggio</span></button></div></header>`;}
function footer(){return `<footer><div class="footer-main"><a class="brand" href="#search" data-action="explore" aria-label="RENT TO A FRIEND · Esplora"><img class="brand-mark" src="/logo-mark.webp" width="96" height="96" alt="" loading="lazy"></a><p>L’attrezzatura si condivide. Le storie si moltiplicano.</p><div><button data-action="how">Come funziona</button><a href="#privacy">Privacy</a><a href="#cookies">Cookie e memoria</a><a href="#terms">Condizioni</a><a href="#data-rights">I tuoi dati</a></div></div><div class="footer-bottom"><span>Da filmmaker a filmmaker, a Roma.</span><span>${isDemo?'Anteprima dimostrativa':'Attrezzatura tra privati'} · RENT TO A FRIEND</span></div></footer><nav class="mobile-nav" aria-label="Navigazione mobile"><a href="#search" data-action="explore" class="${state.route==='search'&&!state.onlyFavorites?'active':''}">${icon('search')}<span>Esplora</span></a><button data-action="show-favorites" class="${state.route==='search'&&state.onlyFavorites?'active':''}" aria-pressed="${state.route==='search'&&state.onlyFavorites}">${icon('heart')}<span>Preferiti</span></button><button class="mobile-publish" data-action="publish"><span class="publish-icon">${icon('plus')}</span><span>Pubblica</span></button><a href="#bookings" class="${state.route==='bookings'?'active':''}" ${state.route==='bookings'?'aria-current="page"':''}>${icon('calendar')}<span>Noleggi</span>${counter('requests')}</a><a href="#messages" class="${state.route==='messages'?'active':''}" ${state.route==='messages'?'aria-current="page"':''}>${icon('chat')}<span>Messaggi</span>${counter('messages')}</a><a href="#profile" class="${state.route==='profile'?'active':''}" ${state.route==='profile'?'aria-current="page"':''}>${icon('user')}<span>Profilo</span></a></nav>`;}
function shell(html){app.dataset.route=state.route;app.innerHTML=header()+`<main id="main">${html}</main>`+footer();enhanceFormFields(app);renderBadges();}
function focusedCatalog(){return Boolean(state.query||state.onlyFavorites||state.category!=='Tutto'||state.zone||state.start||state.end||state.max||state.free||state.brand||state.mount||state.power||state.accessory||state.condition);}
function updateCategoryHint(){const strip=document.querySelector('.category-strip'),list=strip?.querySelector('.categories');if(!list)return;strip.classList.toggle('has-more-categories',list.scrollWidth-list.clientWidth-Math.abs(list.scrollLeft)>2);}
function searchPage(){const focused=focusedCatalog();shell(`<section class="category-strip" aria-label="Categorie di attrezzatura"><div class="categories">${categories.map((c,i)=>`<button data-action="category" data-value="${c}" class="category ${state.category===c?'selected':''}" aria-pressed="${state.category===c}"><span class="category-icon category-icon-${i}">${icon(categoryIcons[i])}</span><span>${c==='Tutto'?'Tutte le categorie':c}</span></button>`).join('')}</div></section><div class="marketplace">${!api.user()?guestAccessPanel({compact:true}):''}<section class="catalog"><div class="catalog-heading"><div><h2>${state.onlyFavorites?'I tuoi preferiti':state.query?'Risultati per “'+esc(state.query)+'”':state.category==='Tutto'?'Attrezzatura vicino a te':esc(state.category)+' per il tuo set'}</h2><p id="results-count" role="status"></p></div><label class="sort-label">Ordina per <select id="sort" aria-label="Ordina annunci"><option value="recommended" ${state.sort==='recommended'?'selected':''}>${isDemo?'Ordine demo':'Più recenti'}</option><option value="price" ${state.sort==='price'?'selected':''}>Prezzo crescente</option><option value="distance" ${state.sort==='distance'?'selected':''}>Distanza dal quartiere</option></select></label></div><div class="catalog-toolbar"><form id="search-form" class="searchbar" aria-label="Zona e date del noleggio"><label class="zone-filter">${icon('pin')}<span><span class="sr-only">Quartiere</span><select name="zone" aria-label="Quartiere">${zoneOptions(state.zone,true)}</select></span></label><label class="date-filter">${icon('calendar')}<span><span>Dal</span><input name="start" type="date" aria-label="Data di ritiro" min="${today()}" value="${state.start}"></span></label><label class="date-filter"><span><span>Al</span><input name="end" type="date" aria-label="Data di restituzione" min="${state.start||today()}" value="${state.end}"></span></label><button class="apply-search" type="submit" aria-label="Applica zona e date">Applica ${icon('check')}</button><p class="form-error" role="alert"></p></form><button class="filter-button ${state.max||state.free||state.brand||state.mount||state.power||state.accessory||state.condition||state.radius!=='10'?'selected':''}" data-action="filters">${icon('sliders')} Filtri${state.max||state.free||state.brand||state.mount||state.power||state.accessory||state.condition||state.radius!=='10'?'<span class="filter-dot"></span>':''}</button></div>${filterChips()}<div id="cards" class="cards"></div><p class="catalog-transparency">${isDemo?'L’ordine iniziale è dimostrativo.':'L’ordine iniziale mostra prima gli annunci più recenti.'} Puoi ordinare per prezzo o distanza stimata dal quartiere. Nessun posizionamento a pagamento. <a href="#terms">Come funzionano annunci e recensioni</a></p><div class="trust-strip"><div>${icon('user')}<span><b>Conosci chi c’è dall’altra parte</b>Apri il profilo prima di noleggiare.</span></div><div>${icon('chat')}<span><b>Accordatevi in chat</b>Dettagli, orari e ritiro, in un solo posto.</span></div><div>${icon('calendar')}<span><b>Solo per i giorni che ti servono</b>Prezzo e cauzione sempre in chiaro.</span></div></div></section>${!focused?`<section class="market-intro"><div><div class="eyebrow">ATTREZZATURA A NOLEGGIO, PERSONE VICINE</div><h1>Il tuo prossimo set, a due passi.</h1><p>Noleggia camere, luci e audio da altri filmmaker a Roma.</p><button class="intro-link" data-action="how">Come funziona ${icon('arrow')}</button></div><div class="intro-art" aria-hidden="true"><span class="art-orbit"></span><div class="intro-camera">${art('camera')}</div><div class="intro-lens">${art('lens')}</div><span class="intro-sticker">Meno spese.<br>Più cinema.</span></div></section>`: ''}${!focused&&state.listings.length?`<section class="community"><div class="community-icon">${icon('camera')}</div><div><h2>La tua attrezzatura ha altre storie da girare.</h2><p>Mettila a noleggio quando non la usi. Il prossimo set è già vicino.</p></div><button class="btn primary" data-action="publish">Crea un annuncio ${icon('plus')}</button></section>`: ''}</div>`);renderCards();updateCategoryHint();document.fonts?.ready.then(updateCategoryHint);}
function filterChips(){const chips=[state.query&&['query',state.query],state.category!=='Tutto'&&['category',state.category],state.onlyFavorites&&['onlyFavorites','Preferiti'],state.start&&['dates',dateLabel(state.start)+' – '+dateLabel(state.end)],state.max&&['max','Fino a '+euro(state.max)+'/giorno'],state.free&&['free','Solo prestiti gratuiti'],state.brand&&['brand',state.brand],state.mount&&['mount',state.mount],state.power&&['power','Da '+state.power+' W'],state.accessory&&['accessory',state.accessory],state.condition&&['condition',state.condition],state.zone&&state.radius!=='10'&&['radius','Entro circa '+state.radius+' km']].filter(Boolean);return chips.length?`<div class="active-filters" aria-label="Filtri attivi">${chips.map(([key,label])=>`<button data-action="clear-filter" data-value="${key}" aria-label="Rimuovi filtro ${esc(label)}">${esc(label)} ${icon('close')}</button>`).join('')}<button class="clear-all" data-action="reset-filters">Azzera tutto</button></div>`:'';}
function zoneOptions(value,all=false){return (all?'<option value="">Tutta Roma</option>':'')+Object.keys(zones).map(z=>`<option ${z===value?'selected':''}>${z}</option>`).join('');}
function filtered(){let list=state.listings.filter(l=>(state.category==='Tutto'||l.category===state.category)&&(!state.query||(l.title+' '+l.description+' '+(l.brand||'')+' '+(l.model||'')).toLowerCase().includes(state.query.toLowerCase()))&&(!state.max||l.price<=Number(state.max))&&(!state.free||l.price===0)&&(!state.onlyFavorites||state.favorites.includes(l.id))&&available(l,state.start,state.end));list=list.filter(l=>matchesTechnical(l,state));if(state.sort==='price')list.sort((a,b)=>a.price-b.price);if(state.sort==='distance'&&state.zone)list.sort((a,b)=>distance(zones[state.zone],zones[a.zone])-distance(zones[state.zone],zones[b.zone]));return list;}
function renderCards(){const list=filtered();document.querySelector('#results-count').textContent=`${list.length} ${isDemo?(list.length===1?'annuncio di prova':'annunci di prova'):(list.length===1?'attrezzatura disponibile':'attrezzature disponibili')} ${state.zone?'entro circa '+state.radius+' km da '+state.zone:'a Roma'}${isDemo?' · Annunci dimostrativi':''}`;document.querySelector('#cards').innerHTML=list.length?list.map(l=>`<article class="card"><div class="card-image ${esc(l.color||'sage')}"><button class="card-open" data-action="detail" data-id="${l.id}" aria-label="Apri ${esc(l.title)}">${photo(l)}</button>${l.price===0?'<span class="card-badge">Prestito gratuito</span>':''}<button class="favorite ${state.favorites.includes(l.id)?'chosen':''}" data-action="favorite" data-id="${l.id}" aria-label="${state.favorites.includes(l.id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${esc(l.title)}" aria-pressed="${state.favorites.includes(l.id)}">${icon('heart')}</button>${!l.images?.length&&isDemo?'<span class="illustration-label">Illustrazione demo</span>':''}</div><div class="card-info"><div class="card-price"><b>${l.price===0?'Gratis':euro(l.price)}</b>${l.price===0?'':'<span> / giorno</span>'}</div><h3><button data-action="detail" data-id="${l.id}">${esc(l.title)}</button></h3><div class="location">${icon('pin')}${esc(l.zone)}${state.zone?' · ~'+distance(zones[state.zone],zones[l.zone]).toFixed(1)+' km':''}</div><button class="card-owner" data-action="public-profile" data-id="${l.owner_id}" aria-label="Profilo di ${esc(l.owner_name||'Filmmaker')}"><span class="mini-avatar">${esc((l.owner_name||'F')[0])}</span><span>${esc(l.owner_name||'Filmmaker')}</span>${isDemo?'<span class="demo-label">Demo</span>':''}</button></div></article>`).join(''):state.onlyFavorites?empty(state.favorites.length?'Nessun preferito disponibile.':'Ancora nessun preferito.','Esplora le attrezzature o rimuovi i filtri per ritrovare i tuoi preferiti.','reset-filters','Esplora le attrezzature'):!state.listings.length?empty('La community sta nascendo.','Pubblica la tua attrezzatura e aiutaci a farla crescere.','publish','Pubblica la tua attrezzatura',true):empty('Nessun annuncio trovato','Prova un’altra categoria o modifica i filtri.','reset-filters','Azzera i filtri');}
function empty(title,body,action,label,community=false){return `<div class="empty${community?' community-empty':''}">${icon('camera')}<h2>${title}</h2><p>${body}</p>${action?`<button class="btn primary" data-action="${action}">${label}</button>`:''}</div>`;}
let lastFocus;
function enhancePasswordFields(root){for(const input of root.querySelectorAll('input[type="password"]')){const label=input.closest('label');if(!label)continue;input.id ||= 'password-'+input.name;label.htmlFor=input.id;const group=document.createElement('div'),field=document.createElement('div'),button=document.createElement('button');group.className='password-group';field.className='password-field';button.type='button';button.className='password-toggle';button.dataset.action='toggle-password';button.setAttribute('aria-controls',input.id);button.setAttribute('aria-label','Mostra password');button.setAttribute('aria-pressed','false');button.innerHTML=icon('eye');label.before(group);group.append(label,field);field.append(input,button);}}
function togglePassword(button){const input=document.getElementById(button.getAttribute('aria-controls'));if(!input||!button.closest('.password-field')?.contains(input))return;const visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-label',visible?'Nascondi password':'Mostra password');button.setAttribute('aria-pressed',String(visible));button.innerHTML=icon(visible?'eye-off':'eye');}
function open(html){captcha.clear();discardPhotoDraft();lastFocus=document.activeElement;modal.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Chiudi">${icon('close')}</button>${html}`;enhanceFormFields(modal);enhancePasswordFields(modal);if(!modal.open)modal.showModal();const protectedForm=modal.querySelector('#auth-form,#reset-form,#automatic-erasure-form');if(protectedForm)captcha.mount(protectedForm).catch(error);}
function close(force=false){if(!force&&modal.querySelector('form[data-submitting="true"]'))return;captcha.clear();discardPhotoDraft();modal.close();lastFocus?.focus();}
modal.addEventListener('close',()=>{captcha.clear();discardPhotoDraft();});
modal.addEventListener('cancel',e=>{if(modal.querySelector('form[data-submitting="true"]'))e.preventDefault();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function discardPhotoDraft(){if(state.photoDraft){for(const p of state.photoDraft.photos)if(p.file)URL.revokeObjectURL(p.url);state.photoDraft=null;}}
function startPhotoDraft(formId,images=[],max=4){state.photoDraft={formId,max,photos:images.map(url=>({url})),busy:false};renderPhotoDraft();}
function photoPicker(avatar=false,handoff=false){return `<label>${avatar?'Foto profilo (facoltativa)':handoff?'Foto (facoltative, fino a 4)':isDemo?'Foto (fino a 4)':'Foto (obbligatorie, da 1 a 4)'}<input type="file" name="photos" accept="image/jpeg,image/png,image/webp" ${avatar?'':'multiple'}></label><p class="fineprint">JPG, PNG o WebP fino a 15 MB. Le foto vengono ridotte prima del caricamento.${avatar?' La foto sarà pubblica: evita documenti e dati sensibili.':handoff?' Fotografa funzionamento, accessori ed eventuali segni. Le immagini restano nel registro privato del noleggio.':' Le foto dell’annuncio saranno pubbliche. Evita volti, documenti e indirizzi precisi. Consigliamo 2–3 foto reali: vista generale, dettagli e accessori. La prima sarà la copertina.'}</p><div id="photo-preview" class="photo-preview" aria-label="Foto selezionate"></div><p id="photo-progress" class="fineprint" role="status"></p>`;}
function renderPhotoDraft(){const draft=state.photoDraft,el=document.querySelector('#photo-preview');if(!draft||!el)return;el.innerHTML=draft.photos.map((p,i)=>`<div class="photo-tile"><img src="${safeImage(p.url)}" alt="Foto ${i+1}${i===0&&draft.formId==='publish-form'?', copertina':''}"><span>${i===0&&draft.formId==='publish-form'?'Copertina':i+1}${p.file?' · '+formatBytes(p.file.size):''}</span>${i>0&&draft.formId==='publish-form'?`<button type="button" class="cover-photo" ${draft.busy?'disabled':''} data-action="photo-cover" data-value="${i}" aria-label="Usa la foto ${i+1} come copertina">Usa come copertina</button>`:''}<button type="button" class="remove-photo" ${draft.busy?'disabled':''} data-action="remove-photo" data-value="${i}" aria-label="Rimuovi foto ${i+1}">×</button></div>`).join('');const status=document.querySelector('#photo-progress');if(status)status.textContent=draft.busy?(draft.saving?'Carico e salvo le foto…':'Preparo le foto…'):draft.photos.length?`${draft.photos.length}/${draft.max} foto${draft.photos.some(p=>p.file)?' · Nuove foto ottimizzate':''}`:'Nessuna foto selezionata.';}
async function addPhotos(input){const formError=input.closest('form')?.querySelector('.form-error');if(formError)formError.textContent='';const draft=state.photoDraft;if(!draft||draft.busy)return;const files=[...input.files];input.value='';validatePhotoBatch([...draft.photos.map(p=>p.file).filter(Boolean),...files]);const replacing=draft.max===1&&files.length===1;if(!replacing&&draft.photos.length+files.length>draft.max)throw new Error('Hai raggiunto il numero massimo di foto. Rimuovine una per sostituirla.');draft.busy=true;const form=input.closest('form'),submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;renderPhotoDraft();const added=[];try{for(const file of files){const prepared=await preparePhoto(file);if(state.photoDraft!==draft)return;added.push({file:prepared,url:URL.createObjectURL(prepared)});}if(replacing){for(const p of draft.photos)if(p.file)URL.revokeObjectURL(p.url);draft.photos=[];}draft.photos.push(...added);added.length=0;}finally{for(const p of added)URL.revokeObjectURL(p.url);draft.busy=false;if(submit)submit.disabled=false;if(state.photoDraft===draft)renderPhotoDraft();}}
async function saveWithPhotos(draft,privateBooking,saveRecord){if(draft?.busy)throw new Error('Attendi che le foto siano pronte.');const refs=[],uploaded=[],photos=[...(draft?.photos||[])];if(draft){draft.busy=true;draft.saving=true;if(state.photoDraft===draft)renderPhotoDraft();}try{for(const p of photos){if(p.file){const ref=await api.upload(p.file,privateBooking,draft.formId==='avatar-form');refs.push(ref);uploaded.push(ref);}else refs.push(p.url);}return await saveRecord(refs);}catch(e){try{await api.removeUploads(uploaded,privateBooking,draft?.formId==='avatar-form');}catch{throw new Error(e.message+' Alcune foto caricate non sono state rimosse: riprova più tardi o contatta il gestore.');}throw e;}finally{if(draft){draft.busy=false;draft.saving=false;if(state.photoDraft===draft)renderPhotoDraft();}}}
function clearPrivateState(){Object.assign(state,{legal:null,bookings:[],threads:[],reviewed:[],currentChat:null,mobileChatOpen:false,reportContext:null,safety:{blocked:[],reports:[],moderator:false},counts:{messages:0,requests:0,byBooking:{}},route:'search'});close(true);location.hash='search';searchPage();}
function guard(){if(api.user())return true;loginDialog();return false;}
async function legalDialog(){
 if(isDemo){open('<h2>Condizioni e privacy</h2><p>La demo non registra accettazioni per account reali. Puoi leggere i documenti dal footer.</p>');return;}
 if(!api.user()){loginDialog();return;}
 state.legal=await api.legalStatus();const doc=state.legal;
 if(!doc.available){open('<h2>Documenti in preparazione</h2><p>Il servizio non ha ancora pubblicato condizioni e informativa definitive. Non puoi creare nuove attività. Puoi gestire i tuoi dati e contattare assistenza@rent-to-a-friend.it.</p><a class="btn secondary" href="#data-rights" data-action="legal-data-rights">I tuoi dati</a>');return;}
 if(typeof doc.terms_text!=='string'||typeof doc.privacy_text!=='string'||doc.terms_text.length>150000||doc.privacy_text.length>150000)throw new Error('I documenti non sono disponibili. Riprova o contatta il gestore.');
 open(`<h2>Condizioni e informativa privacy</h2><p>Versione ${esc(doc.version)}. Leggi i testi prima di scegliere. La presa visione della privacy non è un consenso a ogni trattamento.</p><details open><summary>Condizioni del servizio</summary><div class="legal-document">${legalDocumentMarkup(doc.terms_text)}</div></details><details><summary>Informativa privacy</summary><div class="legal-document">${legalDocumentMarkup(doc.privacy_text)}</div></details>${doc.accepted?`<p>Accettazione registrata il ${new Date(doc.accepted_at).toLocaleString('it-IT')} · Riferimento ${esc(doc.receipt_id)}.</p>`:`<form id="legal-form" class="stack"><label class="check-label"><input type="checkbox" name="terms" required> Ho letto e accetto le condizioni del servizio.</label><label class="check-label"><input type="checkbox" name="privacy_seen" required> Ho preso visione dell’informativa privacy.</label><label class="check-label"><input type="checkbox" name="private_adult" required> Sono maggiorenne e agisco come privato, per scopi estranei ad attività professionali e non per conto di aziende.</label><button class="btn primary" type="submit">Registra accettazione</button><p class="form-error" role="alert"></p></form>`}<p>Puoi consultare ed esportare le ricevute da I tuoi dati. Se non accetti puoi chiudere questa finestra, gestire i rapporti in corso o chiedere la cancellazione.</p>`);
}
function passwordDialog(){const recovery=api.isPasswordRecovery();open(`<h2>${recovery?'Scegli una nuova password':'Cambia password'}</h2><p>${recovery?'Il link email autorizza il recupero: non serve la vecchia password.':'Conferma la password attuale per proteggere il tuo account.'} Dopo il salvataggio dovrai accedere di nuovo.</p><form id="password-form" class="stack">${recovery?'':'<label>Password attuale<input type="password" name="current_password" required maxlength="128" autocomplete="current-password"></label>'}<label>Nuova password<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label>Ripeti la nuova password<input type="password" name="password_confirmation" required minlength="10" maxlength="128" autocomplete="new-password"></label><button class="btn primary">Aggiorna password</button><p class="form-error" role="alert"></p></form>`);}
function authChoices(){return '<div class="auth-choices"><button type="button" class="btn primary" data-action="login">Accedi</button><button type="button" class="btn secondary" data-action="signup">Registrati</button></div>';}
function guestAccessPanel({compact=false}={}){if(compact)return `<aside class="guest-access guest-access-compact" aria-label="Accesso alla community"><p><strong>Esplora senza account.</strong> Accedi per richieste e messaggi.</p>${authChoices()}</aside>`;return `<aside class="guest-access"><h3>Esplora liberamente. Per prenotare, accedi.</h3><p>Annunci, prezzi, profili e recensioni sono consultabili senza account. Per inviare richieste di noleggio o messaggi devi accedere o registrarti.</p>${authChoices()}</aside>`;}
function loginDialog(signup=false){
 const tabs=`<div class="auth-tabs" role="group" aria-label="Accesso o registrazione"><button type="button" data-action="login" aria-pressed="${!signup}" class="${!signup?'selected':''}">Accedi</button><button type="button" data-action="signup" aria-pressed="${signup}" class="${signup?'selected':''}">Registrati</button></div>`;
 if(config.accountCheck&&signup){open(`${tabs}<h2>Crea il tuo account</h2><p>La registrazione non è ancora aperta in questa preview riservata. Se hai già un account RENT TO A FRIEND, scegli Accedi.</p><button class="btn primary" data-action="login">Ho già un account: accedi</button>`);return;}
 open(`${tabs}<div class="modal-heading"><h2>${signup?'Crea il tuo account':'Accedi al tuo account'}</h2><p>${signup?'È la tua prima volta? Registrati con la tua email e confermala dal link che riceverai.':'Hai già un account RENT TO A FRIEND? Inserisci email e password. Questo modulo non crea nuovi account.'}</p>${config.accountCheck?'<p class="fineprint">Collaudo riservato con dati reali: accesso, profilo ed esportazione. Registrazione e recupero password non sono ancora aperti in questa preview.</p>':'<p class="fineprint">Leggi <a href="#privacy" data-action="privacy">privacy</a> e <a href="#terms" data-action="terms">condizioni</a>. Foto e bio sono facoltative.</p>'}</div><div data-google-auth hidden><button type="button" class="btn secondary google-auth" data-action="google-login">${icon('google')} Continua con Google</button><p class="fineprint">Se è il tuo primo accesso con Google, verrà creato un profilo. Se usi la stessa email verificata del tuo account, ritroverai il profilo esistente.</p><p class="auth-divider">oppure usa email e password</p></div><form id="auth-form" class="stack" data-signup="${signup}">${signup?`<p class="privacy-notice">Riservato a privati maggiorenni, per uso personale estraneo ad attività professionali. Dopo la conferma email leggerai le condizioni del servizio.${isDemo?' Gli account reali non sono ancora aperti nella demo.':''}</p><label>Nome visibile<input name="display_name" required minlength="2" maxlength="60" autocomplete="name"></label>`:''}<label>Email<input type="email" name="email" required autocomplete="email"></label>${signup?'<label>Conferma email<input type="email" name="email_confirmation" required autocomplete="off"></label><p class="fineprint">Controlla l’indirizzo: devi poter aprire il link di conferma.</p>':''}<label>Password<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="${signup?'new-password':'current-password'}"></label><button type="submit" class="btn primary">${signup?'Registrati con email':'Accedi con email'}</button><p class="form-error" role="alert"></p></form>${!signup&&!config.accountCheck?'<button type="button" class="text-button" data-action="reset-password">Password dimenticata?</button>':''}<p class="fineprint">${signup?'Hai già un account? Scegli Accedi qui sopra.':'Non hai un account? Scegli Registrati qui sopra.'}</p>`);
 const box=modal.querySelector('[data-google-auth]');api.authOptions().then(options=>{if(box?.isConnected&&options.google)box.hidden=false;}).catch(()=>{});
}


function detail(id){const l=state.listings.find(x=>x.id===id);if(!l)return;const extras=[l.weekend_price!=null&&l.weekend_price!==''?`Weekend ${euro(l.weekend_price)} (ritiro ven/sab, rientro dom/lun)`:'',Number(l.weekly_discount_pct)>0?`−${Number(l.weekly_discount_pct)}% da 7 giorni`:''].filter(Boolean);const d=new Date((state.start||today())+'T12:00:00'),now=new Date(today()+'T12:00:00');state.calendar={listingId:id,offset:Math.max(0,Math.min(11,(d.getFullYear()-now.getFullYear())*12+d.getMonth()-now.getMonth())),start:state.start,end:state.end};open(`${listingGallery(l)}<div class="eyebrow">${esc(l.category)} · ${esc(l.zone)}</div><h2>${esc(l.title)}</h2><button class="person-link" data-action="public-profile" data-id="${l.owner_id}">${icon('user')} Condivisa da ${esc(l.owner_name||'un filmmaker')} ${icon('arrow')}</button>${isDemo?'<p class="fineprint">Annuncio e profilo dimostrativi</p>':''}<div class="technical-chips">${[l.brand,l.model,l.lens_mount,l.light_power_w?l.light_power_w+' W':'',l.equipment_condition,...(l.included_tags||[])].filter(Boolean).map(t=>`<span>${esc(t)}</span>`).join('')}</div><p>${esc(l.description)}</p><div class="detail-facts"><div><span>Noleggio</span><b>${euro(l.price)} / giorno</b></div><div><span>Cauzione separata</span><b>${euro(l.deposit)}</b></div></div>${extras.length?`<p class="pricing-extras">${extras.map(t=>`<span>${esc(t)}</span>`).join('')}</p>`:''}<details open><summary>Accessori inclusi</summary><p>${esc(l.accessories)}</p></details><details><summary>Condizioni e assicurazione</summary><p>${esc(l.conditions)}</p><p>${esc(l.insurance)}</p><p>La piattaforma non fornisce una copertura assicurativa.</p></details><div class="notice">${icon('pin')} L’indirizzo preciso si concorda in chat dopo l’accettazione. La distanza è stimata tra i quartieri.</div>${l.owner_id===api.user()?.id?'<p>Questa è la tua attrezzatura. Gestiscila dal Profilo.</p>':!api.user()?guestAccessPanel():`<button class="btn secondary question-button" data-action="ask-question" data-id="${l.id}">${icon('chat')} Fai una domanda al proprietario</button><div id="rental-calendar">${calendarMarkup(l)}</div><form id="booking-form" class="stack" data-id="${l.id}"><div class="form-grid"><label>Ritiro<input type="date" name="start_date" min="${today()}" value="${state.start}" required></label><label>Restituzione<input type="date" name="end_date" min="${state.start||today()}" value="${state.end}" required></label></div><label>Racconta il tuo progetto<textarea name="note" maxlength="2000" placeholder="Quando vorresti ritirarla? Per che tipo di riprese?" rows="3"></textarea></label><div id="quote" class="quote" role="status"></div><p class="fineprint">Pagamento e cauzione direttamente tra voi. Nessun addebito in app. Le date includono sia il giorno di ritiro sia quello di restituzione.</p><button type="submit" class="btn primary">${isDemo?'Prova la richiesta':'Invia richiesta'} ${icon('arrow')}</button><p class="form-error" role="alert"></p></form>`}${api.user()&&l.owner_id!==api.user().id?`<button class="text-button" data-action="safety-menu" data-id="${l.owner_id}" data-listing="${l.id}">Blocca o segnala questo contatto</button>`:''}`);updateQuote();}
function calendarMarkup(l){const c=state.calendar||{offset:0,start:'',end:''},month=calendarMonth(l,c.offset,c.start,c.end);return `<section class="rental-calendar" aria-label="Disponibilità dell’attrezzatura"><div class="calendar-heading"><h3>${esc(month.title)}</h3><div><button type="button" data-action="calendar-month" data-value="-1" aria-label="Mese precedente" ${c.offset===0?'disabled':''}>‹</button><button type="button" data-action="calendar-month" data-value="1" aria-label="Mese successivo" ${c.offset===11?'disabled':''}>›</button></div></div><div class="calendar-weekdays">${['L','M','M','G','V','S','D'].map(d=>`<span aria-hidden="true">${d}</span>`).join('')}</div><div class="calendar-days">${'<span></span>'.repeat(month.padding)}${month.days.map(d=>`<button type="button" class="calendar-day ${d.blocked?'occupied':''} ${d.inRange?'in-range':''} ${d.selected?'selected':''}" data-action="calendar-day" data-value="${d.date}" aria-label="${esc(dateLabel(d.date))}${d.blocked?', occupato':d.past?', passato':', disponibile'}" aria-pressed="${d.selected}" ${d.blocked||d.past?'disabled':''}>${d.day}</button>`).join('')}</div><p class="calendar-legend"><span>Disponibile</span><span>Occupato</span><button type="button" data-action="calendar-clear">Azzera date</button></p><p class="fineprint">${!c.start?'Scegli il giorno di ritiro, poi quello di restituzione.':!c.end?'Ora scegli la restituzione. Per un solo giorno, tocca di nuovo la stessa data.':period({start_date:c.start,end_date:c.end})}</p><p id="calendar-error" class="form-error" role="alert"></p></section>`;}
function updateCalendar(){const l=state.listings.find(l=>l.id===state.calendar?.listingId),el=document.querySelector('#rental-calendar');if(l&&el)el.innerHTML=calendarMarkup(l);}
function questionDialog(id){if(!guard())return;const l=state.listings.find(l=>l.id===id);if(!l)return;open(`<div class="eyebrow">PRIMA DI PRENOTARE</div><h2>Chiedi a ${esc(l.owner_name||'chi la condivide')}</h2><p>${esc(l.title)}</p><form id="question-form" class="stack" data-id="${id}"><label>La tua domanda<textarea name="body" rows="4" required maxlength="2000" placeholder="È compatibile con la mia camera? La batteria è inclusa?"></textarea></label><p class="fineprint">Apri una conversazione senza prenotare e senza bloccare date.${isDemo?' Nella demo nessuno riceverà il messaggio.':''}</p><button class="btn primary">${icon('chat')} Invia domanda</button><p class="form-error" role="alert"></p></form>`);}
function listingGallery(l){return `<div id="detail-main" class="detail-art ${esc(l.color||'sage')}">${photo(l)}</div>${l.images?.length>1?`<div class="gallery-thumbs" aria-label="Galleria foto">${l.images.map((url,i)=>`<button data-action="gallery-photo" data-id="${l.id}" data-value="${i}" aria-label="Mostra foto ${i+1}" aria-pressed="${i===0}"><img src="${safeImage(url)}" alt="Foto ${i+1}"></button>`).join('')}</div>`:''}`;}
function updateQuote(){const f=document.querySelector('#booking-form');if(!f)return;const l=state.listings.find(l=>l.id===f.dataset.id),start=f.elements.start_date.value,end=f.elements.end_date.value;f.elements.end_date.min=start||today();if(state.calendar){Object.assign(state.calendar,{start,end});updateCalendar();}const box=document.querySelector('#quote'),submit=f.querySelector('button[type=submit]');let days;try{days=validateRental(start,end);if(!available(l,start,end))throw new Error('Il periodo comprende giorni già occupati.');}catch(e){box.textContent=start&&end?e.message:'Scegli ritiro e restituzione per vedere il totale.';submit.disabled=true;return;}const q=quoteRental(l,start,end);box.innerHTML=`<div><span>${days} ${days===1?'giorno':'giorni'} × ${euro(l.price)}</span><b${q.rule==='daily'?'':' class="struck"'}>${euro(q.standard)}</b></div>${q.rule==='daily'?'':`<div><span>${esc(priceRuleLabels[q.rule])}${q.rule==='weekly'?' −'+Number(l.weekly_discount_pct)+'%':''}</span><b>${euro(q.total)}</b></div>`}<div><span>Cauzione separata</span><b>${euro(l.deposit)}</b></div><small>La richiesta non effettua addebiti e non blocca le date finché il proprietario non accetta.</small>`;submit.disabled=false;}
function optionList(values,current,blank='Tutti'){return `<option value="">${blank}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function filtersDialog(){const brands=[...new Set(state.listings.map(l=>l.brand).filter(Boolean))].sort();open(`<h2>Trova il kit giusto.</h2><form id="filters-form" class="stack"><div class="form-grid"><label>Prezzo massimo al giorno (€)<input type="number" name="max" min="0" max="10000" step="1" value="${esc(state.max)}" placeholder="Nessun limite"></label><label>Distanza dal quartiere<select name="radius">${[1,3,5,10,20].map(r=>`<option value="${r}" ${String(r)===state.radius?'selected':''}>Circa ${r} km</option>`).join('')}</select></label></div><p class="fineprint">Scegli un quartiere nella ricerca per applicare la distanza. La stima usa il centro dei quartieri, non l’indirizzo di casa.</p><div class="form-grid"><label>Marca<select name="brand">${optionList(brands,state.brand,'Tutte le marche')}</select></label><label>Attacco<select name="mount">${optionList(mounts,state.mount,'Tutti gli attacchi')}</select></label><label>Potenza luce minima<select name="power">${optionList(['60','120','200','600'],state.power,'Qualsiasi potenza')}</select></label><label>Condizioni<select name="condition">${optionList(conditions,state.condition,'Tutte le condizioni')}</select></label></div><label>Accessorio incluso<select name="accessory">${optionList(accessoryTags,state.accessory,'Qualsiasi accessorio')}</select></label><label class="check-label"><input type="checkbox" name="free" ${state.free?'checked':''}> Solo prestiti gratuiti</label><button class="btn primary">Applica filtri</button><button type="button" class="text-button" data-action="reset-filters">Azzera tutti i filtri</button></form>`);}
async function bookingsPage(){if(!api.user()){shell(empty('I tuoi prossimi set, tutti qui.','Accedi per vedere richieste e prenotazioni.','login','Accedi'));return;}state.bookings=await api.bookings();state.reviewed=await api.reviewedBookings();const list=filterBookings(state.bookings,api.user().id,state.bookingRole,state.bookingGroup);shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">DAL PRIMO CIAO ALL’ULTIMO CIAK</div><h1>Le tue prenotazioni<span>.</span></h1><p>Richieste, ritiri e restituzioni. Tutto in un posto.</p></div><button class="btn secondary" data-action="refresh">${icon('calendar')} Aggiorna</button></div><div class="booking-filters"><div class="filter-tabs" aria-label="Tipo di prenotazione">${[['all','Tutte'],['renter','Cerco attrezzatura'],['owner','La mia attrezzatura']].map(([v,t])=>`<button class="${state.bookingRole===v?'selected':''}" data-action="booking-role" data-value="${v}" aria-pressed="${state.bookingRole===v}">${t}</button>`).join('')}</div><label>Stato <select id="booking-group" aria-label="Stato prenotazioni">${[['all','Tutti gli stati'],['pending','In attesa'],['active','Da ritirare / in corso'],['history','Storico']].map(([v,t])=>`<option value="${v}" ${state.bookingGroup===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="fineprint booking-count">${list.length} ${list.length===1?'prenotazione':'prenotazioni'}</p>${list.length?`<div class="booking-list">${list.map(b=>bookingCard(b)).join('')}</div>`:empty(state.bookings.length?'Nessuna prenotazione con questi filtri.':'Il prossimo set ti aspetta.',state.bookings.length?'Cambia tipo o stato per ritrovare le tue richieste.':'Cerca un’attrezzatura e invia la tua prima richiesta.',state.bookings.length?'reset-booking-filters':'go-search',state.bookings.length?'Mostra tutte':'Esplora attrezzatura')}</section>`);await Promise.all(list.filter(b=>b.owner_id===api.user().id).map(b=>api.readNotifications(b.id,'request',b.created_at)));await refreshCounts();}
function bookingCard(b){const owner=b.owner_id===api.user()?.id;const actions=nextActions(b.status,owner);const actionNames={accepted:'Accetta richiesta',declined:'Rifiuta',cancelled:'Annulla',collected:'Conferma consegna',returned:'Registra restituzione',completed:'Chiudi noleggio'};return `<article class="booking-card"><div class="booking-top"><span class="status ${b.status}">${labels[b.status]}</span><span class="fineprint">${owner?'La tua attrezzatura':'La tua richiesta'}${isDemo?' · Demo':''}</span></div><h2>${esc(b.title)}</h2><button class="person-link" data-action="public-profile" data-id="${owner?b.renter_id:b.owner_id}">${icon('user')} ${owner?'Richiesta di '+esc(b.renter_name||'un filmmaker'):'Vedi il profilo del proprietario'} ${icon('arrow')}</button><div class="booking-meta"><span>${icon('calendar')} ${period(b)}</span><span>Noleggio <b>${euro(b.total)}</b>${b.price_rule&&b.price_rule!=='daily'?' · '+esc(priceRuleLabels[b.price_rule]||''):''}</span><span>Cauzione <b>${euro(b.deposit)}</b></span></div><p>${esc(b.note||'Nessuna nota aggiuntiva.')}</p><details><summary>Accordo e condizioni salvate</summary><p>Accessori: ${esc(b.accessories)}</p><p>Condizioni: ${esc(b.conditions)}</p><p>Assicurazione dichiarata: ${esc(b.insurance)}</p><p>Pagamento esterno. La chiusura non effettua rimborsi o trasferimenti di denaro.</p></details><div class="booking-actions">${b.status==='completed'?(state.reviewed.includes(b.id)?'<span class="review-sent">Recensione inviata</span>':`<button class="btn primary small" data-action="review" data-id="${b.id}">Lascia una recensione</button>`):''}<button class="btn secondary small" data-action="chat" data-id="${b.id}">${icon('chat')} Apri chat</button><button class="btn text small" data-action="evidence" data-id="${b.id}">Registro noleggio</button>${actions.map(a=>`<button class="btn ${['declined','cancelled'].includes(a)?'text':'primary'} small" data-action="transition" data-id="${b.id}" data-value="${a}">${actionNames[a]}</button>`).join('')}${isDemo&&!owner&&b.status==='requested'?`<button class="btn demo-button small" data-action="demo-accept" data-id="${b.id}">Simula accettazione</button>`:''}${isDemo&&!owner&&['accepted','returned'].includes(b.status)?`<button class="btn demo-button small" data-action="demo-handoff" data-id="${b.id}">Simula ${b.status==='accepted'?'consegna':'chiusura'}</button>`:''}</div></article>`;}
function transitionDialog(id,status){
 const b=state.bookings.find(x=>x.id===id),handoff=['collected','returned','completed'].includes(status);
 const guidance=handoff?handoffGuidance(status,b.owner_id===api.user()?.id):null;
 open(`<h2>${({accepted:'Conferma le date',declined:'Rifiuta la richiesta',cancelled:'Annulla la prenotazione',collected:'Pronti per il ciak.',returned:'L’attrezzatura torna a casa.',completed:'Un altro set, concluso.'})[status]}</h2><p>${esc(b.title)} · ${period(b)}</p>
 <form id="transition-form" class="stack" data-id="${id}" data-status="${status}">
 <div class="stack" data-handoff-fields>
 ${handoff?`<div class="handoff-checks"><h3>Controllate insieme</h3><p>${esc(guidance.message)}</p><p class="fineprint">Accessori concordati: ${esc(b.accessories)}</p>${Object.entries(handoffItems).map(([key,label])=>`<label class="check-label"><input type="checkbox" name="check_${key}" required> ${label}</label>`).join('')}<p class="fineprint">Le foto del ritiro e della restituzione restano nel registro, visibili soltanto ai partecipanti.</p></div>${photoPicker(false,true)}`:''}
 <label>Note ${handoff?'sullo stato dell’attrezzatura':''}<textarea name="note" rows="3" maxlength="2000" placeholder="${handoff?'Segna eventuali differenze, danni o accessori mancanti.':'Aggiungi una nota, se necessario.'}"></textarea></label>
 ${status==='completed'?'<div class="notice">Concordate separatamente l’eventuale restituzione della cauzione. L’app non sposta denaro.</div>':''}
 <button type="submit" class="btn primary">${handoff?'Verifica e continua':'Conferma'}</button></div>
 ${handoff?`<section class="handoff-confirmation stack" data-handoff-review hidden tabindex="-1" aria-labelledby="handoff-review-title"><h3 id="handoff-review-title">${esc(guidance.title)}</h3><p>${esc(guidance.message)}</p><p>Se qualcosa non torna, torna ai controlli e aggiorna note e foto prima di confermare. Puoi registrare anche problemi riscontrati: non stai dichiarando che tutto sia privo di difetti.</p><p class="fineprint">Conferma solo dopo lo scambio effettivo. Questo passaggio registra i tuoi controlli e non sostituisce quelli dell’altra persona.</p><button type="submit" class="btn primary" data-handoff-confirm="true">${esc(guidance.confirmLabel)}</button><button type="button" class="btn secondary" data-action="handoff-back">Torna ai controlli</button></section>`:''}
 <p class="form-error" role="alert"></p></form>`);
 if(handoff)startPhotoDraft('transition-form');
}
function showHandoffReview(form,show=true){
 const fields=form.querySelector('[data-handoff-fields]'),review=form.querySelector('[data-handoff-review]');
 if(!review)return;
 fields.hidden=show;review.hidden=!show;
 const target=show?review:fields.querySelector('input,textarea,button');
 target?.focus();target?.scrollIntoView({block:'nearest'});
}
function demoHandoffDialog(id){
 const b=state.bookings.find(x=>x.id===id),status=b.status==='accepted'?'collected':'completed';
 const owner=handoffGuidance(status,true),renter=handoffGuidance(status,false);
 open(`<h2>${status==='collected'?'Simula la consegna':'Simula la chiusura'}</h2><p>${esc(b.title)} · ${period(b)}</p><p class="fineprint">Stai simulando il passaggio del proprietario di esempio. Non viene registrato uno scambio reale.</p><h3>${esc(renter.title)}</h3><p>${esc(renter.message)}</p><h3>${esc(owner.title)}</h3><p>${esc(owner.message)}</p><div class="stack"><button class="btn primary" data-action="confirm-demo-handoff" data-id="${id}">Conferma simulazione</button><button class="btn secondary" data-action="close">Annulla</button></div>`);
}
async function messagesPage(){if(!api.user()){shell(empty('Ogni set inizia con un messaggio.','Accedi per parlare con altri filmmaker.','login','Accedi'));return;}state.threads=await api.chatThreads();if(!state.threads.length){shell(`<section class="page">${empty('Ancora nessuna conversazione.','Apri un annuncio e fai una domanda, anche prima di prenotare.','go-search','Trova attrezzatura')}</section>`);return;}if(!state.currentChat||!state.threads.some(b=>b.id===state.currentChat))state.currentChat=state.threads[0].id;const b=state.threads.find(b=>b.id===state.currentChat),other=b.owner_id===api.user().id?b.renter_id:b.owner_id;const people=new Map(await Promise.all([...new Set(state.threads.map(x=>x.owner_id===api.user().id?x.renter_id:x.owner_id))].map(async id=>{try{return [id,await api.publicProfile(id)];}catch{return [id,{display_name:'Profilo non disponibile'}];}})));const blocked=state.safety.blocked.some(p=>p.id===other);shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">CONOSCI CHI C’È DALL’ALTRA PARTE</div><h1>Messaggi<span>.</span></h1></div><button class="btn secondary" data-action="refresh">Aggiorna</button></div><div class="messenger ${state.mobileChatOpen?'chat-open':''}"><aside class="threads" aria-label="Conversazioni">${state.threads.map(x=>`<button data-action="select-chat" data-id="${x.id}" class="thread ${x.id===b.id?'selected':''}">${avatar(people.get(x.owner_id===api.user().id?x.renter_id:x.owner_id)||{})}<span><b>${esc(people.get(x.owner_id===api.user().id?x.renter_id:x.owner_id)?.display_name||'Filmmaker')}</b><small>${esc(x.title)}</small><small>${period(x)}${x.kind==='inquiry'?'':' · '+labels[x.status]}</small></span><span class="unread-badge" data-thread-count="${x.id}" hidden></span>${icon('arrow')}</button>`).join('')}</aside><div class="conversation"><button class="chat-back" data-action="chat-list">← Tutte le conversazioni</button><div class="conversation-header"><div><b>${esc(b.title)}</b><button class="person-link" data-action="public-profile" data-id="${other}">Vedi il profilo della persona ${icon('arrow')}</button></div><div class="conversation-controls">${b.kind==='inquiry'?`<button class="btn secondary small" data-action="chat-book" data-id="${b.listing_id}">Scegli le date</button>`:`<span class="status ${b.status}">${labels[b.status]}</span>`}<button class="icon-button" data-action="safety-menu" data-id="${other}" data-${b.kind==='inquiry'?'conversation':'booking'}="${b.id}" aria-label="Blocca o segnala questo contatto">${icon('shield')}</button></div></div><p class="conversation-note">${blocked?'Hai bloccato questo profilo. Le conversazioni restano visibili; puoi sbloccarlo dal Profilo.':isDemo?'Demo: i messaggi restano su questo dispositivo e non vengono inviati a persone reali.':b.kind==='inquiry'?'Fai le tue domande. Questa chat non prenota l’attrezzatura e non blocca le date.':'Concordate qui i dettagli del noleggio. L’indirizzo preciso si condivide dopo la conferma.'}</p><div id="messages" class="messages" role="log" aria-label="Messaggi della conversazione"></div><form id="message-form" data-id="${b.id}" data-kind="${b.kind}" class="message-form"><label class="sr-only" for="message-input">Il tuo messaggio</label><input id="message-input" name="body" required maxlength="2000" placeholder="Scrivi un messaggio…" autocomplete="off" ${blocked?'disabled':''}><button class="btn primary" aria-label="Invia messaggio" ${blocked?'disabled':''}>${icon('arrow')}</button><p class="form-error" role="alert"></p></form></div></div></section>`);await loadMessages();}
async function loadMessages(){const id=state.currentChat;const messages=await api.messages(id,state.threads.find(t=>t.id===id)?.kind);if(!document.querySelector('#messages')||state.currentChat!==id)return;const box=document.querySelector('#messages');const signature=JSON.stringify(messages);if(box.dataset.signature===signature)return;const atBottom=!box.dataset.signature||box.scrollHeight-box.scrollTop-box.clientHeight<80;box.dataset.signature=signature;box.innerHTML=messages.length?messages.map(m=>`<div class="bubble ${m.sender_id===api.user().id?'mine':''}"><p>${esc(m.body)}</p><time>${new Date(m.created_at).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>`).join(''):'<p class="empty-chat">Presentati e racconta cosa hai in mente per il tuo set.</p>';if(atBottom)box.scrollTop=box.scrollHeight;if(!document.hidden&&box.getClientRects().length&&messages.length){await api.readNotifications(id,'message',messages.at(-1).created_at,state.threads.find(t=>t.id===id)?.kind);await refreshCounts();}}
function avatar(p,large=false){return `<span class="person-avatar ${large?'large':''}">${p.avatar_url?`<img src="${safeImage(p.avatar_url)}" alt="Foto profilo di ${esc(p.display_name)}">`:esc((p.display_name||'F').trim().slice(0,1).toUpperCase())}</span>`;}
function completionMarkup(p){const c=profileCompleteness(p);return `<div class="profile-completion"><div><b>Profilo completo al ${c.percent}%</b><span>Foto e bio facoltative</span></div><progress value="${c.percent}" max="100" aria-label="Completezza del profilo: ${c.percent}%"></progress>${c.missing.length?`<p class="fineprint">Da aggiungere: ${c.missing.map(esc).join(', ')}.</p>`:''}</div>`;}
async function publicProfileDialog(id){const [p,list,reputation,reviews]=await Promise.all([api.publicProfile(id),api.publicListings(id),api.reputation(id),api.reviews(id)]);const mine=id===api.user()?.id;open(`<div class="public-profile-header">${avatar(p,true)}<div><div class="eyebrow">${isDemo?'PROFILO DIMOSTRATIVO':'NELLA COMMUNITY'}</div><h2>${esc(p.display_name)}</h2><p>${icon('pin')} ${esc(p.zone||'Roma')}</p></div></div><div class="profile-signals">${!isDemo&&p.email_verified?'<span>Email confermata</span>':''}<span>${p.avatar_url?'Foto aggiunta':'Foto non aggiunta'}</span><span>${p.bio?.trim()?'Bio aggiunta':'Bio non aggiunta'}</span></div><div class="reputation-metrics"><div><b>${Number(p.completed_rentals)||0}</b><span>Noleggi conclusi</span></div><div><b>${reputation.review_count?Number(reputation.average_rating).toLocaleString('it-IT',{minimumFractionDigits:1,maximumFractionDigits:1})+' / 5':'—'}</b><span>${Number(reputation.review_count)||0} ${Number(reputation.review_count)===1?'recensione':'recensioni'}</span></div></div>${completionMarkup(p)}<h3>Qualcosa su di me</h3><p class="public-bio">${esc(p.bio?.trim()||'Questa persona non ha ancora aggiunto una bio.')}</p>${p.portfolio_links?.length?`<h3>Portfolio</h3><ul class="portfolio-links">${p.portfolio_links.map(href=>`<li><a href="${esc(href)}" target="_blank" rel="noopener noreferrer nofollow ugc">${esc(portfolioLabel(href))} ${icon('arrow')}</a></li>`).join('')}</ul><p class="fineprint">Link esterni indicati dall’utente: il loro contenuto non è verificato dalla piattaforma.</p>`:''}<p class="fineprint">Le informazioni del profilo sono dichiarate dall’utente. La conferma email non verifica il documento d’identità. Foto, bio e percentuale di completezza non certificano l’affidabilità. I noleggi conclusi sono registrati nell’app, senza verifica indipendente del pagamento o della consegna.</p><h3 class="public-listings-title">Recensioni da noleggi conclusi</h3>${reviews.length?reviews.map(r=>`<article class="review-card"><b>${esc(r.reviewer?.display_name||'Filmmaker')} · ${Number(r.rating)} / 5</b><p>${esc(r.body)}</p><small>${new Date(r.created_at).toLocaleDateString('it-IT')}</small></article>`).join(''):'<p class="fineprint">Nessuna recensione ancora. Non vengono assegnate stelle automatiche.</p>'}<h3 class="public-listings-title">Attrezzatura condivisa · ${list.length}</h3>${list.length?`<div class="public-listings">${list.map(l=>`<button class="public-listing" data-action="profile-listing" data-id="${l.id}"><span>${esc(l.title)}<small>${esc(l.zone)}</small></span><b>${l.price===0?'Gratis':euro(l.price)+'/giorno'}</b>${icon('arrow')}</button>`).join('')}</div>`:'<p>Nessun annuncio attivo. Il profilo serve anche a chi cerca attrezzatura.</p>'}${!mine?`<button class="text-button" data-action="safety-menu" data-id="${id}">Blocca o segnala questo profilo</button>`:''}`);}
function reviewDialog(id){const b=state.bookings.find(b=>b.id===id);if(!b)return;open(`<h2>Com’è andato il noleggio?</h2><p>${esc(b.title)} · ${period(b)}</p><form id="review-form" class="stack" data-id="${id}"><label>Valutazione<select name="rating" required><option value="">Scegli le stelle</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} ${n===1?'stella':'stelle'}</option>`).join('')}</select></label><label>La tua esperienza<textarea name="body" minlength="10" maxlength="1000" rows="4" required placeholder="Puntualità, comunicazione e condizioni dell’attrezzatura…"></textarea></label><p class="fineprint">La recensione sarà pubblica e collegata a questo noleggio concluso. Non inserire indirizzi, telefoni o altri dati privati.</p><button class="btn primary">Pubblica recensione</button><p class="form-error" role="alert"></p></form>`);}
async function safetyMenu(id,context={}){if(!guard())return;state.reportContext=context;const p=await api.publicProfile(id);state.safety=await api.safetySettings();const blocked=state.safety.blocked.some(p=>p.id===id);open(`<h2>Gestisci il contatto</h2><p>${esc(p.display_name)}</p><div class="notice">Bloccare interrompe i nuovi messaggi e le nuove richieste tra voi. Conversazioni e noleggi già creati restano visibili e gestibili.</div><button class="btn secondary" data-action="confirm-block" data-id="${id}" data-value="${!blocked}">${blocked?'Sblocca questo profilo':'Blocca questo profilo'}</button><button class="text-button" data-action="report-user" data-id="${id}">Segnala un problema</button>`);}
function reportDialog(id){open(`<h2>Segnala un problema</h2>${isDemo?'<p class="fineprint">Segnalazione di prova: resta in questo browser e non viene inviata a un operatore. Per contattare il gestore usa l’email indicata nella privacy.</p>':''}<form id="report-form" data-id="${id}" class="stack"><label>Motivo<select name="reason" required>${optionList(reportReasons,'','Scegli un motivo')}</select></label><label>Che cosa è successo?<textarea name="details" rows="4" required minlength="10" maxlength="2000" placeholder="Descrivi i fatti utili a valutare la segnalazione."></textarea></label><p class="fineprint">La segnalazione è riservata e non viene pubblicata sul profilo.${isDemo?' In questa demo verrà salvata solo nel tuo browser.':''}</p><button class="btn primary">${isDemo?'Salva segnalazione demo':'Invia segnalazione'}</button><p class="form-error" role="alert"></p></form>`);}
async function safetySettingsDialog(){state.safety=await api.safetySettings();open(`<h2>Sicurezza e segnalazioni</h2><h3>Profili bloccati</h3>${state.safety.blocked.length?state.safety.blocked.map(p=>`<div class="safety-row"><span>${esc(p.name)}</span><button class="btn secondary small" data-action="confirm-block" data-id="${p.id}" data-value="false">Sblocca</button></div>`).join(''):'<p class="fineprint">Nessun profilo bloccato.</p>'}<h3 class="public-listings-title">Le tue segnalazioni</h3>${state.safety.reports.length?state.safety.reports.map(r=>`<div class="safety-row"><div><b>${esc(r.name)}</b><p>${esc(r.reason)}</p></div><span class="status">${({open:'Da valutare',reviewing:'In verifica',resolved:'Gestita',dismissed:'Archiviata'})[r.status]||'Da valutare'}</span></div>`).join(''):'<p class="fineprint">Nessuna segnalazione inviata.</p>'}${isDemo?'<p class="fineprint">La demo non invia segnalazioni a moderatori reali.</p>':''}${state.safety.moderator?'<button class="btn primary" data-action="moderation">Apri gestione segnalazioni</button>':''}`);}
async function moderationDialog(){const rows=await api.moderationQueue();open(`<h2>Gestione segnalazioni</h2><p>Salvare l’esito aggiorna soltanto la pratica: non sospende account, non rimuove annunci e non invia email. Prima di chiuderla, verifica l’intervento e il riscontro alle persone interessate.</p>${rows.length?rows.map(r=>`<article class="review-card"><h3>${esc(r.reported_name)}</h3><b>${esc(r.reason)}</b><p>${esc(r.details)}</p><p class="fineprint">Stato: ${esc(r.status)}</p><form id="moderation-${r.id}" class="stack moderation-form" data-id="${r.id}"><label>Esito<select name="status"><option value="">Scegli uno stato</option>${[['reviewing','In verifica'],['resolved','Gestita'],['dismissed','Archiviata']].map(([value,label])=>`<option value="${value}" ${value===r.status?'selected':''}>${label}</option>`).join('')}</select></label><label>Nota interna<textarea name="note" maxlength="1000">${esc(r.moderator_note||'')}</textarea></label><button class="btn secondary">Salva esito</button><p class="form-error" role="alert"></p></form></article>`).join(''):'<p>Nessuna segnalazione.</p>'}`);}
async function avatarDialog(){const p=await api.profile();open(`<h2>Fatti riconoscere.</h2><p>La foto è facoltativa e visibile a chi visita il tuo profilo.</p><form id="avatar-form" class="stack">${photoPicker(true)}<button type="submit" class="btn primary">Salva foto profilo</button><p class="form-error" role="alert"></p></form>`);startPhotoDraft('avatar-form',p.avatar_url?[p.avatar_url]:[],1);}
async function notificationPanel(){let status;try{status=await push.status();}catch{status=push.capabilities();}const iosHelp=status.ios&&!status.installed;return `<section class="panel notifications-panel"><div class="eyebrow">RESTIAMO IN CONTATTO</div><h2>Notifiche</h2><p>${isDemo?'Nella demo puoi vedere contatori di prova per messaggi e richieste. Non vengono inviate notifiche push.':'Se le attivi, le notifiche ti avvisano di nuovi messaggi e richieste anche quando non stai guardando l’app.'}</p><p class="notification-status" role="status">${isDemo?'Nella demo vedi i contatori nell’app. Le notifiche tra utenti reali non sono attive in questa versione.':iosHelp?'Aggiungi prima l’app alla schermata Home dell’iPhone.':!status.supported?'Questo browser non supporta le notifiche push.':status.permission==='denied'?'Notifiche bloccate nelle impostazioni del browser.':status.enabled?'Attive su questo dispositivo.':'Non ancora attive su questo dispositivo.'}</p>${iosHelp?'<ol class="install-steps"><li>Apri il sito in Safari.</li><li>Tocca Condividi → Aggiungi alla schermata Home.</li><li>Apri l’app dall’icona e torna qui per attivarle.</li></ol>':''}<form id="notification-form" class="stack"><label class="check-label"><input type="checkbox" name="messages" ${status.messages!==false?'checked':''}> Nuovi messaggi</label><label class="check-label"><input type="checkbox" name="requests" ${status.requests!==false?'checked':''}> Nuove richieste di noleggio</label><button type="submit" class="btn primary" ${isDemo||iosHelp||!status.supported?'disabled':''}>${status.enabled?'Salva preferenze':'Attiva notifiche'}</button><p class="form-error" role="alert"></p></form>${status.enabled?'<button class="text-button" data-action="disable-push">Disattiva su questo dispositivo</button>':''}<button class="text-button" data-action="install-app">Come aggiungere l’app alla Home</button><p class="fineprint">Puoi disattivarle quando vuoi. ${isDemo?'Questa demo non invia email.':'Le email del servizio sono riservate a conferma dell’indirizzo e recupero password.'}</p></section>`;}
function installDialog(){open('<h2>La tua app, sempre a portata.</h2><p>Su iPhone: apri in Safari, tocca Condividi e scegli Aggiungi alla schermata Home. Se compare, attiva Apri come app web. Poi apri dall’icona: da Profilo puoi autorizzare le notifiche.</p><p>Su Android o computer: cerca Installa app o Aggiungi alla schermata Home nel menu del browser.</p><button class="btn primary" data-action="close">Ho capito</button>');}
function myListingCard(l,archived=false){return `<article class="my-listing ${archived?'archived':''}"><div class="my-art ${esc(l.color||'sage')}">${photo(l)}</div><div><h3>${esc(l.title)}</h3><p>${euro(l.price)}/giorno · ${esc(l.zone)} · ${archived?'Archiviato':l.active?'Pubblicato':'In pausa'}</p>${archived?'':`<p class="fineprint">${(l.blocked||[]).length} periodi bloccati</p>`}<div class="booking-actions">${archived?`<button class="btn secondary small" data-action="restore-listing" data-id="${l.id}">Ripristina in pausa</button>`:`<button class="btn secondary small" data-action="toggle-listing" data-id="${l.id}" data-value="${!l.active}">${l.active?'Metti in pausa':'Ripubblica'}</button><button class="btn secondary small" data-action="edit-listing" data-id="${l.id}">Modifica</button><button class="btn text small" data-action="availability" data-id="${l.id}">Disponibilità</button><button class="btn text small" data-action="archive-listing" data-id="${l.id}">Archivia</button>`}</div></div></article>`;}
function myListingsMarkup(mine){const current=mine.filter(l=>!l.archived),archived=mine.filter(l=>l.archived);return (current.length?current.map(l=>myListingCard(l)).join(''):empty('Falla uscire dalla borsa.','Pubblica la tua prima attrezzatura.','publish','Crea annuncio'))+(archived.length?`<details class="listing-archive panel"><summary>Archivio annunci · ${archived.length}</summary><p class="fineprint">Gli annunci archiviati restano salvati insieme allo storico. Puoi ripristinarli in pausa e ripubblicarli quando vuoi.</p>${archived.map(l=>myListingCard(l,true)).join('')}</details>`:'');}
async function archiveListingDialog(id){const l=(await api.myListings()).find(l=>l.id===id&&!l.archived);if(!l)throw new Error('Annuncio non trovato.');open(`<h2>Archiviare questo annuncio?</h2><p><b>${esc(l.title)}</b></p><p>Non comparirà nel catalogo o sul profilo pubblico. Annuncio, foto e storico dei noleggi restano salvati; potrai ripristinarlo in pausa dal tuo archivio.</p><p class="fineprint">Prima dell’archiviazione devi gestire eventuali richieste pendenti o noleggi in corso.</p><form id="archive-listing-form" class="stack" data-id="${l.id}"><button type="submit" class="btn primary">Archivia annuncio</button><button type="button" class="btn secondary" data-action="close">Annulla</button><p class="form-error" role="alert"></p></form>`);}
async function profilePage(){if(!api.user()){shell(`<section class="page"><h1>Il tuo profilo</h1>${guestAccessPanel()}</section>`);return;}const [p,mine,notifications]=await Promise.all([api.profile(),api.myListings(),notificationPanel()]);shell(`<section class="page"><div class="page-heading"><div><div class="eyebrow">IL TUO ANGOLO DI COMMUNITY</div><h1>Ciao, ${esc(p?.display_name||'filmmaker')}<span>.</span></h1><p>${isDemo?'Stai usando un profilo demo, salvato solo in questo browser.':esc(api.user().email)}</p></div><button class="btn secondary" data-action="${isDemo?'reset-demo':'logout'}">${isDemo?'Ripristina demo':'Esci'}</button></div><div class="profile-shortcuts"><a href="#bookings">${icon('calendar')} I miei noleggi ${counter('requests')} ${icon('arrow')}</a><a href="#messages">${icon('chat')} I miei messaggi ${counter('messages')} ${icon('arrow')}</a></div><div class="profile-grid"><div><div class="profile-identity panel">${avatar(p||{},true)}<h2>${esc(p?.display_name||'Il tuo profilo')}</h2>${completionMarkup(p)}<p class="fineprint">${isDemo?'Profilo dimostrativo':p?.email_verified?'Email confermata':'Email da confermare'}</p><button class="btn secondary small" data-action="edit-avatar">${p?.avatar_url?'Cambia foto':'Aggiungi foto profilo'}</button><button class="text-button" data-action="public-profile" data-id="${api.user().id}">Guarda il tuo profilo pubblico</button></div><form id="profile-form" class="panel stack"><h2>Il tuo profilo</h2><label>Nome visibile<input name="display_name" value="${esc(p?.display_name||'')}" required minlength="2" maxlength="60"></label><label>Il tuo quartiere<select name="zone" required>${zoneOptions(p?.zone||'Prati')}</select></label><label>Qualcosa su di te (facoltativo)<textarea name="bio" maxlength="600" rows="4">${esc(p?.bio||'')}</textarea></label><fieldset class="portfolio-fields"><legend>Portfolio (facoltativo)</legend><p class="fineprint">Fino a ${PORTFOLIO_MAX} link https: Vimeo, Instagram, IMDb, il tuo sito. Saranno pubblici sul profilo.</p>${Array.from({length:PORTFOLIO_MAX},(_,i)=>`<label>Link ${i+1} (facoltativo)<input name="portfolio" type="text" inputmode="url" autocomplete="url" maxlength="300" value="${esc(p?.portfolio_links?.[i]||'')}" placeholder="${['vimeo.com/tuonome','instagram.com/tuonome','imdb.com/name/…','tuosito.it'][i]}"></label>`).join('')}</fieldset><button class="btn primary">Salva profilo</button><p class="form-error" role="alert"></p></form></div><div><div class="section-title"><h2>La tua attrezzatura</h2><button class="btn primary small" data-action="publish">${icon('plus')} Aggiungi</button></div>${myListingsMarkup(mine)}${notifications}<section class="panel safety-panel"><h2>I tuoi dati</h2><p class="fineprint">Privacy, esportazione e richiesta di cancellazione.</p><a class="btn secondary" href="#data-rights">Gestisci i tuoi dati</a></section><section class="panel safety-panel"><h2>La tua sicurezza</h2><p class="fineprint">Gestisci contatti bloccati e segnalazioni.</p><button class="btn secondary" data-action="safety-settings">Sicurezza e segnalazioni</button><button class="btn secondary" data-action="change-password">Cambia password</button></section></div></div></section>`);}
function publishDialog(listing=null){if(!guard())return;const editing=Boolean(listing),v=k=>esc(listing?.[k]??'');open(`<div class="eyebrow">UN’ATTREZZATURA, NUOVE POSSIBILITÀ</div><h2>${editing?'Il tuo annuncio, aggiornato.':'Cosa metti in comune?'}</h2>${editing?'<p class="fineprint">Le modifiche valgono per le nuove richieste. Prezzi e condizioni delle richieste già inviate restano quelli salvati.</p>':''}<form id="publish-form" class="stack" ${editing?`data-id="${listing.id}"`:''}><label>Titolo dell’annuncio<input name="title" value="${v('title')}" required minlength="5" maxlength="90" placeholder="Es. Sony A7 IV + 2 batterie"></label><div class="form-grid"><label>Categoria<select name="category" required>${categories.slice(1).map(c=>`<option ${listing?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Quartiere<select name="zone" required>${zoneOptions(listing?.zone||'Prati')}</select></label></div><label>Descrizione<textarea name="description" required minlength="20" maxlength="2000" rows="3" placeholder="Descrivi attrezzatura, condizioni e utilizzi consigliati.">${v('description')}</textarea></label><fieldset class="technical-fields"><legend>Dettagli tecnici (facoltativi)</legend><div class="form-grid"><label>Marca<input name="brand" maxlength="40" value="${v('brand')}" placeholder="Es. Sony"></label><label>Modello<input name="model" maxlength="60" value="${v('model')}" placeholder="Es. FX3"></label><label>Attacco<select name="lens_mount">${optionList(mounts,listing?.lens_mount||'','Non applicabile')}</select></label><label>Potenza luce (W)<input name="light_power_w" type="number" min="1" max="20000" step="1" value="${v('light_power_w')}" placeholder="Se applicabile"></label></div><label>Condizioni dell’attrezzatura<select name="equipment_condition">${optionList(conditions,listing?.equipment_condition||'','Da specificare')}</select></label><div class="accessory-options">${accessoryTags.map(t=>`<label class="check-label"><input type="checkbox" name="included_tags" value="${t}" ${listing?.included_tags?.includes(t)?'checked':''}> ${t}</label>`).join('')}</div></fieldset><div class="form-grid"><label>Prezzo al giorno (€)<input type="number" name="price" value="${v('price')}" min="0" max="10000" step="0.01" required placeholder="0 per un prestito gratuito"></label><label>Cauzione (€)<input type="number" name="deposit" value="${listing?.deposit??0}" min="0" max="100000" step="0.01" required></label></div><div class="form-grid"><label>Prezzo weekend (€, facoltativo)<input type="number" name="weekend_price" value="${listing?.weekend_price??''}" min="0" max="10000" step="0.01" placeholder="Es. 50"></label><label>Sconto da 7 giorni (%, facoltativo)<input type="number" name="weekly_discount_pct" value="${listing?.weekly_discount_pct||''}" min="0" max="50" step="1" placeholder="Es. 15"></label></div><p class="fineprint">Il prezzo weekend vale per ritiro venerdì o sabato e rientro domenica o lunedì, se conviene rispetto alla tariffa giornaliera. Lo sconto si applica a noleggi di almeno 7 giorni. Il totale è calcolato dal server.</p><label>Accessori inclusi<textarea name="accessories" required maxlength="1500" rows="2" placeholder="Elenca esattamente cosa consegnerai.">${v('accessories')}</textarea></label><label>Condizioni di noleggio<textarea name="conditions" required maxlength="1500" rows="2" placeholder="Orari, precauzioni, cosa deve portare chi ritira…">${v('conditions')}</textarea></label><label>Copertura assicurativa dichiarata<textarea name="insurance" required maxlength="1000" rows="2">${editing?v('insurance'):'Nessuna copertura inclusa.'}</textarea></label><p class="fineprint">Se esiste una polizza, descrivi copertura, esclusioni e requisiti. La piattaforma non vende né garantisce assicurazioni.</p>${photoPicker()}<p class="fineprint">Il servizio è riservato agli scambi tra privati. Non pubblicare per conto di aziende o nell’ambito di un’attività professionale.</p><label class="check-label"><input type="checkbox" name="private_use" required> Dichiaro di agire come privato, per scopi estranei a un’attività imprenditoriale o professionale e non per conto di un’azienda.</label><label class="check-label"><input type="checkbox" required> Confermo di poter mettere a noleggio questa attrezzatura e che le informazioni sono corrette.</label><button type="submit" class="btn primary">${editing?'Salva modifiche':isDemo?'Pubblica nella demo':'Pubblica annuncio'} ${icon('arrow')}</button><p class="form-error" role="alert"></p></form>`);startPhotoDraft('publish-form',listing?.images||[]);}
async function route(){const [path,query='']=location.hash.slice(1).split('?');state.route=path||'search';const linked=(new URLSearchParams(query).get('conversation')||new URLSearchParams(query).get('booking'));if(linked&&/^[a-f0-9-]{36}$/i.test(linked)){state.currentChat=linked;state.mobileChatOpen=true;}if(!['search','messages','bookings','profile','privacy','cookies','terms','data-rights'].includes(state.route))state.route='search';try{if(state.route==='cookies')shell('<section class="page legal-page">'+cookiesMarkup(isDemo)+'</section>');if(state.route==='privacy')shell('<section class="page legal-page">'+privacyMarkup(false)+'</section>');if(state.route==='terms')shell('<section class="page legal-page">'+termsMarkup(false)+'</section>');if(state.route==='data-rights')await dataRightsPage();if(state.route==='search')searchPage();if(state.route==='bookings')await bookingsPage();if(state.route==='messages')await messagesPage();if(state.route==='profile')await profilePage();}catch(e){shell(empty('Non siamo riusciti a caricare la pagina.',esc(e.message),'refresh','Riprova'));}}
function go(where){if(location.hash==='#'+where)route();else location.hash=where;}
